			/* @Override */
			public void keyReleased(KeyEvent e) {
				KeyboardFocusManager kfm = KeyboardFocusManager.getCurrentKeyboardFocusManager();
				kfm.redispatchEvent(textArea, e);
			}

			/* @Override */
			public void keyPressed(KeyEvent e) {
